test("reject reason required scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "perm-void", "steward");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "1");
  await ui.setSetting(pg_uma, "score-log", "on");
  await ui.setSetting(pg_uma, "pending-sla", "4");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": "ADA@X"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "0.40", "start": "2026-03-01", "end": "2026-04-30", "every": "10"}));
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "C", "gradeFrom": "2026-02-25"})).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.importRates(pg_uma, "A,12.50\nB,12.50,2026-03-05")).toBe(2);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "0.04", "date": "2026-02-25", "note": "n", "ref": " r-1 "})).toBeNull();
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);

